tests.harness:
class V:
    def sonido(self):
        return 'v'
class W:
    def sonido(self):
        return 'w'
assert sonidos([V(), W(), V()]) == ['v', 'w', 'v']

class Cuadrado:
    def __init__(self, l):
        self.l = l
    def area(self):
        return self.l * self.l
assert area_total([Cuadrado(2), Cuadrado(3)]) == 13
